function createCua(bindings) {
  const clone = value => JSON.parse(JSON.stringify(value));
  const object = (value, name) => {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new TypeError(`${name} must be an object`);
    return value;
  };
  const exactKeys = (value, keys, name) => {
    object(value, name);
    for (const key of Object.keys(value)) if (!keys.includes(key)) throw new TypeError(`${name}: unknown field ${key}`);
    return value;
  };
  const nonempty = (value, name) => {
    if (typeof value !== 'string' || !value.length) throw new TypeError(`${name} must be a nonempty string`);
    return value;
  };
  const invoke = async (role, args) => {
    const declared = bindings[role];
    if (!declared || typeof tools[declared.name] !== 'function') throw new Error(`No declared ${role} capability in this context`);
    const result = await tools[declared.name](args);
    object(result, 'admitted tool result');
    if (result.tool !== declared.tool || result.ok !== true || !result.body) {
      const error = new Error(result.error?.message ?? `${role} did not return a successful admitted result`);
      error.result = result;
      throw error;
    }
    return result.body;
  };
  const sameApp = (a, b) => a?.host_generation === b?.host_generation && a?.app_instance_id === b?.app_instance_id;
  const boundedUtf8 = (value, maximum, name) => {
    if (typeof value !== 'string') throw new TypeError(`${name} must be a string`);
    let bytes = 0;
    for (const point of value) {
      const code = point.codePointAt(0);
      if (code >= 0xd800 && code <= 0xdfff) throw new Error(`${name} contains invalid UTF8`);
