  const observationOptions = (options, name) => {
    exactKeys(options, ['emit','disableDiffing'], name);
    for (const key of ['emit','disableDiffing']) if (options[key] !== undefined && typeof options[key] !== 'boolean') throw new TypeError(`${key} must be boolean`);
    return options;
