  const presentation = (observation, previous, requestedBase) => {
    const p = exactKeys(observation.presentation, ['schema_version','format','context_type','mode','base_revision','text','rendered_element_ids','focused_element_id','selected_text','selected_element_ids'], 'native AX presentation');
