    };
    ids(p.rendered_element_ids, currentIds, 'Native rendered IDs');
    ids(p.selected_element_ids, currentIds, 'Native selected IDs');
    if (p.focused_element_id !== null && !currentIds.has(p.focused_element_id)) throw new Error('Native focus is absent from retained AX nodes');
