    click:['app_click',['element_id','window_id','image_id','x','y','button','count']],
    move:['app_move',['window_id','image_id','x','y']],
    drag:['app_drag',['window_id','image_id','from_x','from_y','to_x','to_y']],
    scroll:['app_scroll',['window_id','element_id','image_id','x','y','direction','pages','delta_x','delta_y']],
    pressKey:['app_key',['window_id','key','key_code','modifiers']],
    typeText:['app_type',['window_id','text']],
    paste:['app_paste',['window_id','text','format']],
    selectText:['app_select_text',['window_id','element_id','text','prefix','suffix','selection_type']],
    performSecondaryAction:['app_secondary_action',['window_id','element_id','action_id']],
    setValue:['app_set_value',['window_id','element_id','value']],
