  const api = Object.create(null);
  if (bindings.apps) api.getApps = async () => invoke('apps', {});
  if (bindings.status) api.getState = async () => invoke('status', {});
  if (bindings.control) api.control = async mode => invoke('control', {mode});
  if (bindings.cancel) api.cancel = async args => invoke('cancel', args);
