        const observed = await invoke('app_state', args);
        const next = object(observed.evidence?.application, 'application state');
        const application = object(next.application, 'application identity');
        nonempty(application.bundle_id, 'bundle_id');
        nonempty(application.bundle_path, 'bundle_path');
        nonempty(application.app?.host_generation, 'host_generation');
        nonempty(application.app?.app_instance_id, 'app_instance_id');
        if (state && (application.bundle_id !== state.application.bundle_id || application.bundle_path !== state.application.bundle_path)) throw new Error('The resolved application target changed');
        if (!/^sha256:[0-9a-f]{64}$/.test(observed.app_grant_request_id ?? '')) throw new Error('State has no admitted app grant reference');
        if (next.accessibility?.mode !== 'full' || !Array.isArray(next.accessibility.nodes)) throw new Error('A complete full AX observation carrier is required; no guessed diff merge');
        if (!Array.isArray(next.windows) || !Array.isArray(next.captures)) throw new Error('State has no window/capture evidence');
        const ax = next.accessibility;
        if (!sameApp(ax.app, application.app) || next.scope?.host_generation !== application.app.host_generation || !Number.isSafeInteger(ax.revision) || ax.revision <= 0 || ax.nodes.length > 4096 || typeof ax.complete !== 'boolean' || !Array.isArray(ax.omissions) || ax.complete !== (ax.omissions.length === 0)) throw new Error('Native AX identity, revision or completeness differs from its state');
        nonempty(next.scope.worker_environment_id, 'worker_environment_id');
        nonempty(next.scope.formation_pin, 'formation_pin');
        nonempty(ax.observation_id, 'observation_id');
        if (ax.base_revision !== null || !Array.isArray(ax.removed_ids) || ax.removed_ids.length !== 0) throw new Error('The raw AX carrier must remain full and independent of display diff');
        exactKeys(ax.context, ['root_kind','root_element_id','menu_bar_element_id','display_omissions'], 'native AX context');
        const rootRoles = {application:'AXApplication', menu_bar_item:'AXMenuBarItem', menu:'AXMenu'};
        if (!Object.hasOwn(rootRoles, ax.context.root_kind) || !ax.nodes.some(n => n.element_id === ax.context.root_element_id && n.role === rootRoles[ax.context.root_kind])) throw new Error('Native AX context does not name its exact retained root');
        if (ax.context.menu_bar_element_id !== null && !ax.nodes.some(n => n.element_id === ax.context.menu_bar_element_id && n.role === 'AXMenuBar')) throw new Error('Native AX menu bar is not retained');
