        primaryCapture(next);
        body = clone(observed); state = body.evidence.application; grant = body.app_grant_request_id;
        renderedState = renderState();
        target = {kind:'bundle_path', value:application.bundle_path};
        if (ax.complete) completeBase = {app:clone(ax.app), observation_id:ax.observation_id, revision:ax.revision};
        actionable = true;
        return clone(state);
      } finally { busy = false; }
    };
    const window = id => {
      nonempty(id, 'window_id');
      if (!current().windows.some(w => w.window_id === id && sameApp(w.app, state.application.app))) throw new Error('window_id is absent from this App observation');
      return id;
    };
    const node = id => {
      nonempty(id, 'element_id');
      const matches = current().accessibility.nodes.filter(n => n.element_id === id);
      if (matches.length !== 1) throw new Error('element_id does not identify one observed AX node');
      return matches[0];
    };
    const capture = id => {
      nonempty(id, 'image_id');
      const matches = current().captures.filter(c => c.image.image_id === id && sameApp(c.app, state.application.app));
      if (matches.length !== 1) throw new Error('image_id does not identify one captured image');
      return matches[0];
    };
    const targetArgs = (role, args) => {
      if (args.element_id !== undefined) {
        const n = node(args.element_id);
        if (args.window_id !== undefined && args.window_id !== n.window_id) throw new Error('window_id differs from the AX association');
        if (n.window_id === null) {
          if (n.window_unavailable_reason !== 'ax_window_attribute_unavailable' || !['app_click','app_set_value','app_select_text','app_secondary_action'].includes(role)) throw new Error('This operation requires an available native window association');
          return {...args, window_id:null};
        }
        if (n.window_unavailable_reason !== null) throw new Error('AX window association has an unavailable reason');
        return {...args, window_id:window(n.window_id)};
      }
      if (args.image_id !== undefined) {
        const c = capture(args.image_id);
        if (args.window_id !== undefined && args.window_id !== c.window.window_id) throw new Error('window_id differs from the captured window');
        for (const [x,y] of [['x','y'],['from_x','from_y'],['to_x','to_y']]) {
          if (args[x] === undefined && args[y] === undefined) continue;
          if (!Number.isFinite(args[x]) || !Number.isFinite(args[y]) || args[x] < 0 || args[y] < 0 || args[x] >= c.image.width || args[y] >= c.image.height) throw new Error('Coordinates must be inside the original captured image');
        }
        return {...args, window_id:window(c.window.window_id)};
      }
      if (['app_key','app_type','app_paste'].includes(role) && (args.window_id === null || args.window_id === undefined)) return {...args, window_id:null};
      return {...args, window_id:window(args.window_id)};
    };
    const mutate = async (role, args, fields) => {
      exactKeys(args, fields, role);
      if (busy || !actionable) throw new Error('Obtain fresh App state before this action');
      const authored = targetArgs(role, args);
      const a = current().accessibility;
      const request = {...authored, grant_request_id:grant, app:clone(state.application.app), observation_id:a.observation_id, revision:a.revision, control_generation:state.control_generation};
      busy = true; actionable = false;
      try { return await invoke(role, request); }
      finally { busy = false; }
    };
    const app = Object.create(null);
    Object.defineProperty(app, 'state', {enumerable:true, get:() => clone(current())});
    Object.defineProperty(app, 'grantRequestId', {enumerable:true, get:() => grant});
    app.getAXState = async (options = {}) => {
      observationOptions(options, 'getAXState options');
      await update(true, options.disableDiffing === true);
      if (options.emit !== false) text(renderedState);
      return renderedState;
    };
    app.getScreenshot = async (options = {}) => {
      exactKeys(options, ['emit'], 'getScreenshot options');
      if (options.emit !== undefined && typeof options.emit !== 'boolean') throw new TypeError('emit must be boolean');
      await update(true);
      const selected = primaryCapture(current());
      if (!selected) throw new Error('Screenshot unavailable for this application observation');
      const carrier = imageCarrier(selected);
      if (options.emit !== false) emitImage(selected, carrier);
      return carrier.bytes;
    };
    app.getAXStateAndScreenshot = async (options = {}) => {
      observationOptions(options, 'getAXStateAndScreenshot options');
      await update(true, options.disableDiffing === true);
      const selected = primaryCapture(current());
      const carrier = selected ? imageCarrier(selected) : undefined;
      if (options.emit !== false) {
        text(renderedState);
        if (carrier) emitImage(selected, carrier);
      }
      return carrier ? {state:renderedState, screenshot:carrier.bytes} : {state:renderedState};
    };
    app.getNode = id => clone(node(id));
    app.getCapture = id => clone(capture(id));
    app.pixelToScreen = (imageId, x, y) => {
      const c = capture(imageId), m = c.geometry.pixel_to_screen;
      if (!Number.isFinite(x) || !Number.isFinite(y) || x < 0 || y < 0 || x >= c.image.width || y >= c.image.height || !Array.isArray(m) || m.length !== 6 || !m.every(Number.isFinite)) throw new Error('Invalid captured pixel or native transform');
