      const windows = s.windows.filter(w => w.window_id === primary.source_window_id && sameApp(w.app, s.application.app));
      if (windows.length !== 1) throw new Error('Primary capture lost its exact application window');
      if (primary.image_id === null) {
        if (!Array.isArray(s.capture_omissions) || s.capture_omissions.filter(o => o.window_id === primary.source_window_id).length !== 1 || s.captures.some(c => c.window.window_id === primary.source_window_id)) throw new Error('Uncaptured primary window has no exact omission');
        return undefined;
      }
