      const captures = s.captures.filter(c => c.image.image_id === primary.image_id);
      if (captures.length !== 1) throw new Error('Primary image is absent or repeated');
      const c = captures[0];
      const source = exactKeys(c.source, ['primary_window_incarnation','contributors','crop_screen_points','filter_mode'], 'native capture source');
      if (!sameApp(c.app, s.application.app) || !sameApp(c.window.app, s.application.app) || c.window.window_id !== primary.source_window_id || source.primary_window_incarnation !== primary.source_window_incarnation || !Array.isArray(source.contributors) || source.contributors.length < 1 || source.contributors.length > 2) throw new Error('Primary image changed its native source');
      const first = exactKeys(source.contributors[0], ['kind','window_id','window_incarnation'], 'primary contributor');
      if (first.kind !== 'application_window' || first.window_id !== primary.source_window_id || first.window_incarnation !== primary.source_window_incarnation) throw new Error('Primary image has a foreign application contributor');
      const cursor = source.contributors[1];
      if (cursor !== undefined) {
        exactKeys(cursor, ['kind','cg_window_id','host_generation'], 'owned cursor contributor');
        if (cursor.kind !== 'owned_cursor' || !Number.isInteger(cursor.cg_window_id) || cursor.cg_window_id <= 0 || cursor.cg_window_id > 4294967295 || cursor.host_generation !== s.application.app.host_generation || s.windows.some(w => w.cg_window_id === cursor.cg_window_id)) throw new Error('Primary image has a foreign cursor contributor');
      }
